<script>
 let {record,records=[],onopen}= $props();
 const label=id=>records.find(r=>r.id===id)?.name||id||'None';
 const open=id=>id&&onopen?.(id);
</script>
{#if record?.type==='location'}
<section class="domain-summary" data-domain="politics"><h3>Political control</h3>
 <p>Recognized ruler <button onclick={()=>open(record.data.politics.rulingHouseId)} disabled={!record.data.politics.rulingHouseId}>{label(record.data.politics.rulingHouseId)}</button></p>
 <p>Actual controller <button onclick={()=>open(record.data.politics.controllerHouseId)} disabled={!record.data.politics.controllerHouseId}>{label(record.data.politics.controllerHouseId)}</button></p>
 <small>Applies to this place. Containment does not transfer its political control.</small>
 <h4>Claims</h4>{#each record.data.politics.claims as claim}<article>{#if typeof claim==='string'}<button onclick={()=>open(claim)}>{label(claim)}</button>{:else}<button onclick={()=>open(claim.houseId)}>{label(claim.houseId)}</button><strong>{claim.status}</strong><p>{claim.basis}</p><small>{claim.from||'Date unknown'} to {claim.until||'open'} · {claim.visibility}</small>{#each claim.evidenceIds as source}<button class="source" onclick={()=>open(source)}>{label(source)}</button>{/each}{/if}</article>{/each}
 <h4>Control and occupation history</h4>{#each record.data.politics.controlHistory||[] as interval}<article><button onclick={()=>open(interval.controllerHouseId)} disabled={!interval.controllerHouseId}>{label(interval.controllerHouseId)}</button><strong>{interval.mode}</strong><p>Recognized ruler: <button onclick={()=>open(interval.recognizedRulerHouseId)} disabled={!interval.recognizedRulerHouseId}>{label(interval.recognizedRulerHouseId)}</button></p><small>{interval.from||'Date unknown'} to {interval.until||'present'} · {interval.visibility}</small>{#each interval.evidenceIds as source}<button class="source" onclick={()=>open(source)}>{label(source)}</button>{/each}</article>{:else}<p>No occupation history recorded.</p>{/each}
</section>
{:else if record?.type==='resource'}
<section class="domain-summary" data-domain="rights"><h3>Ownership and access</h3><p>Owner <button onclick={()=>open(record.data.ownerHouseId)} disabled={!record.data.ownerHouseId}>{label(record.data.ownerHouseId)}</button></p><p>Controller <button onclick={()=>open(record.data.controllerHouseId)} disabled={!record.data.controllerHouseId}>{label(record.data.controllerHouseId)}</button></p><p>Located at <button onclick={()=>open(record.data.locationId)}>{label(record.data.locationId)}</button></p><h4>Access rights</h4>{#each record.data.accessRights||[] as right}<article><button onclick={()=>open(right.houseId)}>{label(right.houseId)}</button><strong>{right.kind}</strong><p>{right.scope}</p><small>{right.from||'Date unknown'} to {right.until||'open'} · {right.visibility}</small>{#each right.evidenceIds as source}<button class="source" onclick={()=>open(source)}>{label(source)}</button>{/each}</article>{:else}<p>No access terms recorded.</p>{/each}</section>
{:else if record?.type==='character'}
<section class="domain-summary" data-domain="knowledge"><h3>Knowledge and beliefs</h3>{#each record.data.knowledge as claim}<article><strong>{claim.kind==='belief'?'Belief, not established truth':'Actor knowledge'}</strong><p>{claim.text}</p><small>Confidence {Math.round(claim.confidence*100)}% · {claim.visibility}</small>{#each claim.acquisitions||[] as acquisition}<p><button onclick={()=>open(acquisition.actorId)}>{label(acquisition.actorId)}</button> {acquisition.method} · {acquisition.worldTime||'Time unknown'}{#if acquisition.fromActorId} from <button onclick={()=>open(acquisition.fromActorId)}>{label(acquisition.fromActorId)}</button>{/if}</p>{#each acquisition.evidenceIds as source}<button class="source" onclick={()=>open(source)}>{label(source)}</button>{/each}{/each}{#each claim.beliefProvenance||[] as belief}<p><button onclick={()=>open(belief.actorId)}>{label(belief.actorId)}</button> · {belief.assessment} · {Math.round(belief.confidence*100)}% · {belief.worldTime||'Time unknown'}</p><p>{belief.reason}</p>{#if belief.sourceActorId}<button onclick={()=>open(belief.sourceActorId)}>{label(belief.sourceActorId)}</button>{/if}{#each belief.basisEvidenceIds as source}<button class="source" onclick={()=>open(source)}>{label(source)}</button>{/each}{/each}</article>{:else}<p>No personally known claims recorded.</p>{/each}</section>
{/if}
<style>
.domain-summary{border:1px solid #354035;border-radius:8px;padding:12px;margin:14px 0;font-size:12px}h3{font-size:13px;color:#c6a66c;margin:0 0 12px}h4{font-size:12px;margin:14px 0 7px;color:#bec2b6}p{margin:7px 0;overflow-wrap:anywhere}small{display:block;color:#92998a;font-size:11px}article{border-top:1px solid #283027;padding:9px 0}strong{display:block;font-size:11px;font-weight:500;color:#a6b598;margin:5px 0}button{font:inherit;background:#20271f;color:#dcded3;border:1px solid #354035;border-radius:4px;padding:3px 7px;cursor:pointer}button:hover{border-color:#b79860}button:disabled{opacity:.7;cursor:default}.source{font-size:10px;margin:4px 4px 0 0}
</style>
